/**
 * Browser Local character library.
 *
 * A deliberately small cast of fictional, generic illustrated adults that the
 * story engine reuses across campaigns. Nothing here is generated by a model,
 * downloaded, or licensed: each character is a set of colours plus a layered
 * pose description that the browser renderer draws with plain geometry.
 *
 * The point of the library is continuity — once a campaign picks a character,
 * the same face, hair and clothing appear in every scene of that campaign.
 *
 * Pure module: data and geometry parameters only. No canvas, no clock.
 */

export type CharacterId =
  | "RENTER_CHARACTER_01"
  | "HOST_CHARACTER_01"
  | "NEUTRAL_CHARACTER_01"
  | "SECONDARY_CHARACTER_01";

export type CharacterRole = "renter" | "host" | "neutral" | "secondary";

export type Pose =
  | "standing"
  | "walking"
  | "lookingAround"
  | "worried"
  | "thinking"
  | "holdingBox"
  | "carryingBoxes"
  | "pointing"
  | "lookingAtPhone"
  | "openingGarage"
  | "presenting"
  | "waving"
  | "placingBox"
  | "relieved";

export type Expression =
  | "neutral"
  | "concerned"
  | "confused"
  | "searching"
  | "thinking"
  | "hopeful"
  | "relieved"
  | "happy"
  | "confident";

/** Lightweight deterministic motion primitives. No skeletal animation engine. */
export type CharacterMotion =
  | "idle"
  | "walkIn"
  | "walkOut"
  | "gesture"
  | "point"
  | "lookAround"
  | "lookAtPhone"
  | "pickUp"
  | "putDown"
  | "nod"
  | "smallWave"
  | "relief";

/** Palette for one character. Fixed per character so continuity is automatic. */
export type CharacterDesign = {
  id: CharacterId;
  name: string;
  role: CharacterRole;
  skin: string;
  hair: string;
  hairStyle: "short" | "bob" | "tied";
  top: string;
  sleeve: string;
  trousers: string;
  shoes: string;
  accent: string;
};

/**
 * How the body is arranged for a pose. Angles are radians measured from the
 * shoulder/hip downwards, so 0 is straight down and positive swings forward.
 */
export type PoseSpec = {
  lean: number;
  crouch: number;
  headTilt: number;
  headTurn: number;
  armFar: { shoulder: number; elbow: number };
  armNear: { shoulder: number; elbow: number };
  legFar: number;
  legNear: number;
  /** What the hands are holding, drawn between them where relevant. */
  carry: "none" | "box" | "boxes" | "phone";
  /** Slight vertical offset, used for reaching or setting something down. */
  lift: number;
};

