/** Eyes and mouth for an expression, in head-local units (head radius = 1). */
export type ExpressionSpec = {
  browTilt: number;
  eyeOpen: number;
  eyeLook: number;
  mouthCurve: number;
  mouthWidth: number;
};

const EXPRESSIONS: Record<Expression, ExpressionSpec> = {
  neutral: { browTilt: 0, eyeOpen: 1, eyeLook: 0, mouthCurve: 0, mouthWidth: 0.34 },
  concerned: { browTilt: 0.34, eyeOpen: 0.92, eyeLook: -0.1, mouthCurve: -0.3, mouthWidth: 0.3 },
  confused: { browTilt: -0.3, eyeOpen: 1.05, eyeLook: 0.2, mouthCurve: -0.15, mouthWidth: 0.26 },
  searching: { browTilt: 0.12, eyeOpen: 1.1, eyeLook: 0.34, mouthCurve: -0.05, mouthWidth: 0.28 },
  thinking: { browTilt: 0.2, eyeOpen: 0.86, eyeLook: 0.26, mouthCurve: -0.08, mouthWidth: 0.24 },
  hopeful: { browTilt: -0.12, eyeOpen: 1.08, eyeLook: 0.16, mouthCurve: 0.22, mouthWidth: 0.32 },
  relieved: { browTilt: -0.06, eyeOpen: 0.7, eyeLook: 0, mouthCurve: 0.3, mouthWidth: 0.36 },
  happy: { browTilt: -0.1, eyeOpen: 0.66, eyeLook: 0, mouthCurve: 0.52, mouthWidth: 0.44 },
  confident: { browTilt: -0.05, eyeOpen: 0.96, eyeLook: 0.05, mouthCurve: 0.32, mouthWidth: 0.38 },
};

export const CHARACTER_IDS = Object.keys(CHARACTERS) as CharacterId[];
export const POSE_IDS = Object.keys(POSES) as Pose[];
export const EXPRESSION_IDS = Object.keys(EXPRESSIONS) as Expression[];

export function hasCharacter(id: string): id is CharacterId {
  return Object.prototype.hasOwnProperty.call(CHARACTERS, id);
}

export function character(id: CharacterId): CharacterDesign {
  const found = CHARACTERS[id];
  if (!found) throw new Error(`Unknown character: ${id}`);
  return found;
}

export function pose(id: Pose): PoseSpec {
  return POSES[id] ?? POSES.standing;
}

export function expression(id: Expression): ExpressionSpec {
  return EXPRESSIONS[id] ?? EXPRESSIONS.neutral;
}

export function isPose(value: string): value is Pose {
  return Object.prototype.hasOwnProperty.call(POSES, value);
}

export function isExpression(value: string): value is Expression {
  return Object.prototype.hasOwnProperty.call(EXPRESSIONS, value);
}

/** Registration point, so future artwork can be added without a rewrite. */
export function addCharacter(design: CharacterDesign): void {
  CHARACTERS[design.id] = design;
}

/** The character the story engine should use for a given side of the market. */
export function characterForRole(role: CharacterRole): CharacterId {
  const match = CHARACTER_IDS.find((id) => CHARACTERS[id]!.role === role);
  return match ?? "NEUTRAL_CHARACTER_01";
}
